Here's a complete example. I'll use a hypothetical "todos" REST API to demonstrate the patterns.

---

### **Tools/TodoApiTools.cs** — Tool class wrapping a REST API

```csharp
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

[McpServerToolType]
public class TodoApiTools(HttpClient httpClient, ILogger<TodoApiTools> logger)
{
    [McpServerTool, Description("Get a todo item by its ID.")]
    public async Task<string> GetTodo(
        [Description("The numeric ID of the todo item")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching todo {Id}", id);
        var todo = await httpClient.GetFromJsonAsync<TodoItem>(
            $"/todos/{id}", cancellationToken);
        return $"Todo #{todo!.Id}: {todo.Title} (completed: {todo.Completed})";
    }

    [McpServerTool, Description("List all todos, optionally filtered by completion status.")]
    public async Task<string> ListTodos(
        [Description("Filter: true=completed only, false=pending only, omit=all")] bool? completed = null,
        CancellationToken cancellationToken = default)
    {
        var url = completed.HasValue
            ? $"/todos?completed={completed.Value}"
            : "/todos";

        var todos = await httpClient.GetFromJsonAsync<List<TodoItem>>(
            url, cancellationToken);

        return string.Join("\n", todos!.Select(t =>
            $"#{t.Id}: {t.Title} [{(t.Completed ? "✓" : "○")}]"));
    }

    [McpServerTool(Destructive = false, ReadOnly = false),
     Description("Create a new todo item.")]
    public async Task<string> CreateTodo(
        [Description("Title of the new todo item")] string title,
        CancellationToken cancellationToken = default)
    {
        var response = await httpClient.PostAsJsonAsync("/todos",
            new { title, completed = false }, cancellationToken);
        response.EnsureSuccessStatusCode();
        var created = await response.Content.ReadFromJsonAsync<TodoItem>(
            cancellationToken: cancellationToken);
        return $"Created todo #{created!.Id}: {created.Title}";
    }
}

public record TodoItem(
    [property: JsonPropertyName("id")] int Id,
    [property: JsonPropertyName("title")] string Title,
    [property: JsonPropertyName("completed")] bool Completed);
```

---

### **Program.cs** — Stdio transport with DI

```csharp
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);

// CRITICAL for stdio: log to stderr only, stdout is the JSON-RPC channel
builder.Logging.AddConsole(options =>
    options.LogToStandardErrorThreshold = LogLevel.Trace);

builder.Services.AddHttpClient<TodoApiTools>(client =>
{
    client.BaseAddress = new Uri("https://jsonplaceholder.typicode.com");
});

builder.Services.AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();
```

---

### How DI works for MCP tools

The SDK supports **two injection styles**:

| Style | Class type | How services arrive |
|-------|-----------|---------------------|
| **Constructor injection** | Non-static class | Services in primary constructor (shown above) |
| **Method parameter injection** | Static class | Services as method params, resolved per-call |

**Key rules:**
1. **DI parameters are hidden from LLMs** — `HttpClient`, `ILogger<T>`, `CancellationToken`, `IMcpServer`, and any DI-registered service are automatically injected and **never** appear in the tool's JSON schema.
2. **Only `[Description]`-annotated parameters are exposed** — these become the tool's input schema that the LLM sees and fills in.
3. **`WithToolsFromAssembly()`** discovers all `[McpServerToolType]` classes via reflection and registers them. For non-static classes (like `TodoApiTools`), the SDK creates instances through DI, so constructor dependencies must be registered in `builder.Services`.

In the example above, `AddHttpClient<TodoApiTools>(...)` registers both `IHttpClientFactory` and a typed `HttpClient` that gets injected into the constructor. `ILogger<T>` is registered automatically by the host builder.
